this.client = new lazy.LDAPClient(url.host, port, useSecureTransport);
this._url = url;
this._bindName = bindName;
this.client.onOpen = () => {
  listener.onLDAPInit();
};
this.client.onError = (status, secInfo) => {
  listener.onLDAPError(status, secInfo, `${url.host}:${port}`);
};
this.client.connect();
